sys_script_include.script:
var DoppelIOCImport = Class.create();
DoppelIOCImport.prototype = {
    initialize: function () {
        this.STAGING_TABLE = 'x_doppe_doppel_t_0_staging';
        this.CONFIG_TABLE = 'x_doppe_doppel_t_0_doppel_configuration';
        this.NO_MATCH_TEXT = 'No Doppel alert for this value';
        this._config = null;
    },

    // ---------------------------------------------------------------
    // Configuration (Doppel TI Configuration record)
    // ---------------------------------------------------------------

    // Settings used by every feature. Read once per object from the single
    // Doppel TI Configuration record; defaults apply when no record exists.
    _cfg: function () {
        if (this._config) return this._config;
		var ALL_PRODUCTS = ['domains', 'email', 'telco', 'social_media', 'darkweb',
                            'mobile_apps', 'ecommerce', 'crypto', 'paid_ads'];
        var c = {
            found: false,
            version: 'v1',
            apiKey: '', userKey: '', orgCode: '', clientId: '', clientSecret: '',
			products: ALL_PRODUCTS.slice(),
            historicalDays: 7,
            pageSize: 200,
            promoteQueue: ['needs_confirmation', 'monitoring', 'actioned'],
            promoteEntity: ['active', 'suspicious'],
            promoteSeverity: ['high'],
            maliciousQueue: ['actioned', 'taken_down']
        };
        var gr = new GlideRecord(this.CONFIG_TABLE);
        gr.orderBy('sys_created_on');
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            c.found = true;
            c.version = gr.getValue('api_version') == 'v2' ? 'v2' : 'v1';
            c.apiKey = gr.api_key.getDecryptedValue() || '';
            c.userKey = gr.user_api_key.getDecryptedValue() || '';
            c.orgCode = String(gr.getValue('organisation_code') || '').trim();
            c.clientId = String(gr.getValue('client_id') || '').trim();
            c.clientSecret = gr.client_secret.getDecryptedValue() || '';
			// "Import all Doppel products" ticked → every product; otherwise only the ticked ones
            c.products = this._isTrue(gr.getValue('import_all_doppel_products'))
                ? ALL_PRODUCTS.slice()
                : this._checked(gr, {
                    domains: 'import_domains', email: 'import_email', telco: 'import_telco',
                    social_media: 'import_social_media', darkweb: 'import_dark_web',
                    mobile_apps: 'import_mobile_apps', ecommerce: 'import_ecommerce',
                    crypto: 'import_crypto', paid_ads: 'import_paid_ads'
                });
			c.historicalDays = Math.min(parseInt(gr.getValue('historical_days'), 10) || 7, 30);
			c.promoteQueue = this._checked(gr, {
                needs_confirmation: 'promote_queue_needs_confirmation',
                monitoring: 'promote_queue_monitoring', actioned: 'promote_queue_actioned'
            });
            c.promoteEntity = this._checked(gr, {
                active: 'promote_entity_active', suspicious: 'promote_entity_suspicious', parked: 'promote_entity_parked'
            });
            c.promoteSeverity = this._checked(gr, {
                high: 'promote_severity_high', medium: 'promote_severity_medium'
            });
            c.maliciousQueue = this._checked(gr, {
                actioned: 'malicious_queue_actioned', taken_down: 'malicious_queue_taken_down',
                doppel_review: 'malicious_queue_doppel_review', needs_confirmation: 'malicious_queue_needs_confirmation',
                monitoring: 'malicious_queue_monitoring'
            });
        }
        this._config = c;
        return c;
    },

    // Test Connectivity: use values typed on the form (not yet saved) on top of the stored ones.
	withConfig: function (override) {
        var c = this._cfg();
        var storedClientId = c.clientId;
        for (var k in override) {
            if (override.hasOwnProperty(k)) c[k] = override[k];
        }
        this._config = c;
        this._v2Token = null;
        this._v2TokenExpiry = null;
        // Mint a new v2 token only if new v2 credentials are being tested
        this._forceNewToken = !!(override.clientSecret || (override.clientId && override.clientId != storedClientId));
        return this;
    },

    _checked: function (gr, map) {
        var out = [];
        for (var value in map) {
            if (map.hasOwnProperty(value) && this._isTrue(gr.getValue(map[value]))) out.push(value);
        }
        return out;
    },

    _isTrue: function (v) {
        return v == '1' || v == 'true' || v === true;
    },

    // ---------------------------------------------------------------
    // Scheduled import
    // ---------------------------------------------------------------

    importAlerts: function (maxPages, importSetTable) {
        var since = this._getImportSince();
        var pageSize = this._cfg().pageSize || 200;
        var staged = 0, failed = 0, page = 0, totalPages = 1;
        var complete = true;
        var maxActivity = '';

        gs.info('DoppelIOCImport: import started | since=' + since + ' | page_size=' + pageSize);

        while (page < totalPages) {
            if (maxPages && page >= maxPages) { complete = false; break; } // test runs never move the watermark
            var body = this._fetchPage(page, since, pageSize);
            if (!body) {
                complete = false;
                gs.error('DoppelIOCImport: failed to fetch page ' + page + ', stopping this run');
                break;
            }
            totalPages = (body.metadata && body.metadata.total_pages) || 0;
            var alerts = body.alerts || [];
			// NEW: one line per page so the run's progress is visible
            gs.info('DoppelIOCImport: page ' + (page + 1) + '/' + totalPages + ' fetched | alerts on page=' + alerts.length +
                    (page == 0 && body.metadata ? ' | total alerts in window=' + body.metadata.count : ''));
            for (var i = 0; i < alerts.length; i++) {
                try {
                    if (importSetTable) importSetTable.insert(this._toStagingRow(alerts[i]));
                    else this._stageAlert(alerts[i]);
                    staged++;
                    var ts = alerts[i].last_activity_timestamp || alerts[i].created_at || '';
                    if (ts > maxActivity) maxActivity = ts; // same ISO format, so string compare works
                } catch (e) {
                    failed++;
                    gs.error('DoppelIOCImport: error staging alert ' + (alerts[i].id || 'unknown') + ': ' + e.message);
                }
            }
            page++;
        }

        if (complete) {
            if (maxActivity) this._setProperty('x_doppe_doppel_t_0.import_watermark', maxActivity);
            gs.info('DoppelIOCImport: watermark ' + (maxActivity ? 'advanced to ' + maxActivity : 'unchanged (no alerts)'));
        } else {
            gs.warn('DoppelIOCImport: run incomplete, watermark NOT advanced; next run retries from ' + since);
        }
        gs.info('DoppelIOCImport: staging complete | staged=' + staged + ' | failed=' + failed +
                ' | pages=' + page + (totalPages ? '/' + totalPages : ''));   // NEW: pages fetched
        return staged;
    },

    _getImportSince: function () {
        var wm = gs.getProperty('x_doppe_doppel_t_0.import_watermark', '');
        if (wm) return wm;
        var days = this._cfg().historicalDays || 7;
        var gdt = new GlideDateTime();
        gdt.addDaysUTC(-days);
        return gdt.getValue().replace(' ', 'T'); // UTC, same shape as Doppel's timestamps
    },

    _setProperty: function (name, value) {
        var p = new GlideRecord('sys_properties');
        p.addQuery('name', name);
        p.query();
        if (p.next()) {
            p.setValue('value', value);
            p.update();
            return true;
        }
        gs.error('DoppelIOCImport: property not found: ' + name);
        return false;
    },

    getIndicatorDecision: function (queueState, entityState, severity) {
        var q = String(queueState || '').toLowerCase();
        var e = String(entityState || '').toLowerCase();
        var s = String(severity || '').toLowerCase();

        if (q == 'archived' || e == 'unrelated')
            return { action: 'revoke', reason: 'dismissed or unrelated (queue=' + q + ', entity=' + e + ')' };
        if (q == 'taken_down' || e == 'down')
            return { action: 'deactivate', reason: 'threat no longer live (queue=' + q + ', entity=' + e + ')' };

        var c = this._cfg();
        if (c.promoteQueue.indexOf(q) > -1 && c.promoteEntity.indexOf(e) > -1 && c.promoteSeverity.indexOf(s) > -1)
            return { action: 'promote', reason: 'meets promotion criteria' };

        return { action: 'none', reason: 'does not meet promotion criteria (queue=' + q + ', entity=' + e + ', severity=' + s + ')' };
    },

    isProductIngested: function (product) {
        return this._cfg().products.indexOf(String(product || '').toLowerCase()) > -1;
    },

    fetchAndTransform: function (maxPages) {
        // Staging rows are transformed synchronously as they are inserted (import set mode: Synchronous),
        // so no separate transform call and no Global-scope helper is needed.
        return this.importAlerts(maxPages);
    },

    _fetchPage: function (page, since, pageSize) {
        var headers = this._getAuthHeaders();
        if (!headers) {
            gs.error('DoppelIOCImport: _fetchPage aborted for page ' + page + ' — no valid auth headers');
            return null;
        }
        var MAX_ATTEMPTS = 3;
        for (var attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            try {
                var r = new sn_ws.RESTMessageV2();
                r.setEndpoint(this._getApiBase() + '/alerts');
                r.setHttpMethod('GET');
                for (var key in headers) {
                    r.setRequestHeader(key, headers[key]);
                }
                r.setQueryParameter('page', page.toString());
                r.setQueryParameter('page_size', String(pageSize || 30));
                if (since) r.setQueryParameter('last_activity_timestamp', since);
                r.setHttpTimeout(30000);

                var response = r.execute();
                var httpStatus = response.getStatusCode();
                if (httpStatus == 200) {
                    return JSON.parse(response.getBody());
                }

                // 429 (rate limit), 5xx (Doppel server error) and 0 (no response) are worth retrying
                var retryable = (httpStatus == 429 || httpStatus >= 500 || httpStatus == 0);
                gs.warn('DoppelIOCImport: page ' + page + ' attempt ' + attempt + '/' + MAX_ATTEMPTS +
                        ' → HTTP ' + httpStatus + ': ' + String(response.getBody()).substring(0, 300));
                if (!retryable) return null; // e.g. 400/401/403: retrying won't help
            } catch (e) {
                gs.warn('DoppelIOCImport: page ' + page + ' attempt ' + attempt + '/' + MAX_ATTEMPTS +
                        ' → exception: ' + e.message);
            }
        }
        gs.error('DoppelIOCImport: page ' + page + ' failed after ' + MAX_ATTEMPTS + ' attempts');
        return null;
    },

    _toStagingRow: function (alert) {
        var ip = (alert.entity_content && alert.entity_content.root_domain)
            ? (alert.entity_content.root_domain.ip_address || '') : '';
        return {
            alert_id: alert.id || '',
            entity: alert.entity || '',
            brand: alert.brand || '',
            queue_state: alert.queue_state || '',
            entity_state: alert.entity_state || '',
            severity: alert.severity != null ? String(alert.severity) : '',
            score: alert.score != null ? String(alert.score) : '',
            product: alert.product || '',
            platform: alert.platform || '',
            source: alert.source || '',
            notes: alert.notes || '',
            created_at: alert.created_at || '',
            last_activity_timestamp: alert.last_activity_timestamp || '',
            doppel_link: alert.doppel_link || '',
            screenshot_url: alert.screenshot_url || '',
            message: alert.message || '',
            assignee: alert.assignee || '',
            uploaded_by: alert.uploaded_by || '',
            alert_summary: alert.alert_summary || '',
            tags: alert.tags ? JSON.stringify(alert.tags) : '',
            audit_logs: alert.audit_logs ? JSON.stringify(alert.audit_logs) : '',
            entity_content: alert.entity_content ? JSON.stringify(alert.entity_content) : '',
            entity_ip_address: ip
        };
    },

    _stageAlert: function (alert) {
        var row = this._toStagingRow(alert);
        var gr = new GlideRecord(this.STAGING_TABLE);
        gr.initialize();
        for (var f in row) gr.setValue('u_' + f, row[f]);
        gr.insert();
    },

    // ---------------------------------------------------------------
    // Local search and Doppel alert API
    // ---------------------------------------------------------------

	searchLocal: function (value) {
        var P = 'x_doppe_doppel_t_0_';
        var obs = new GlideRecord('sn_ti_observable');
        obs.addQuery('value', value);
        obs.addQuery(P + 'doppel_owned', true);
        obs.addNotNullQuery(P + 'alert_id');
        obs.setLimit(1);
        obs.query();
        if (!obs.next()) return null;
        var link = new GlideRecord('sn_ti_m2m_observable_indicator');
        link.addQuery('observable', obs.getUniqueValue());
        link.addQuery('indicator.' + P + 'doppel_owned', true);
        link.setLimit(1);
        link.query();
        return {
            observable_sys_id: obs.getUniqueValue(),
            has_indicator: link.hasNext(),
            alert_id: obs.getValue(P + 'alert_id') || '',
            brand: obs.getValue(P + 'brand') || '',
            product_type: obs.getValue(P + 'product') || '',
            queue_state: obs.getValue(P + 'queue_state') || '',
            entity_state: obs.getValue(P + 'entity_state') || '',
            doppel_link: obs.getValue(P + 'doppel_link') || ''
        };
    },

    getAlertByEntity: function (entityValue) {
        var headers = this._getAuthHeaders();
        if (!headers) {
            return { success: false, error: 'No valid auth headers (check the Doppel TI Configuration)' };
        }
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this._getApiBase() + '/alert');
            r.setHttpMethod('GET');
            for (var key in headers) {
                r.setRequestHeader(key, headers[key]);
            }
            r.setQueryParameter('entity', entityValue);
            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();
            if (status == 200) {
                return { success: true, data: JSON.parse(body) };
            } else if (status == 404) {
                return { success: true, data: null };
            }
            gs.error('Doppel getAlertByEntity failed: HTTP ' + status + ' - ' + String(body).substring(0, 300));
            return { success: false, error: 'HTTP ' + status, raw: body };
        } catch (e) {
            gs.error('Doppel getAlertByEntity exception: ' + e.message);
            return { success: false, error: e.message };
        }
    },

    getAlertById: function (alertId) {
        var headers = this._getAuthHeaders();
        if (!headers) {
            return { success: false, error: 'No valid auth headers (check the Doppel TI Configuration)' };
        }
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this._getApiBase() + '/alert');
            r.setHttpMethod('GET');
            for (var key in headers) {
                r.setRequestHeader(key, headers[key]);
            }
            r.setQueryParameter('id', alertId);
            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();
            if (status == 200) {
                return { success: true, data: JSON.parse(body) };
            } else if (status == 404) {
                return { success: true, data: null };
            }
            gs.error('Doppel getAlertById failed: HTTP ' + status + ' - ' + String(body).substring(0, 300));
            return { success: false, error: 'HTTP ' + status, raw: body };
        } catch (e) {
            gs.error('Doppel getAlertById exception: ' + e.message);
            return { success: false, error: e.message };
        }
    },

    createAlertInDoppel: function (entityValue, brand, source) {
        var headers = this._getAuthHeaders();
        if (!headers) {
            return { success: false, error: 'No valid auth headers (check the Doppel TI Configuration)' };
        }
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this._getApiBase() + '/alert');
            r.setHttpMethod('POST');
            for (var key in headers) {
                r.setRequestHeader(key, headers[key]);
            }
            r.setRequestHeader('Content-Type', 'application/json');
            var payload = { entity: entityValue };
            if (brand) payload.brand = brand;
            if (source) payload.source = source;
            r.setRequestBody(JSON.stringify(payload));
            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();
            if (status == 200 || status == 201) {
                return { success: true, alreadyExisted: (status == 200), data: JSON.parse(body) };
            } else if (status == 409) {
                return { success: false, error: 'Entity exists under a different brand', raw: body };
            } else if (status == 400) {
                var errMsg = 'Invalid request';
                try {
                    var parsedErr = JSON.parse(body);
                    if (parsedErr.message) errMsg = parsedErr.message;
                } catch (e2) { /* fall back to generic message */ }
                return { success: false, error: errMsg, raw: body };
            }
            gs.error('Doppel createAlertInDoppel failed: HTTP ' + status + ' - ' + String(body).substring(0, 300));
            return { success: false, error: 'HTTP ' + status, raw: body };
        } catch (e) {
            gs.error('Doppel createAlertInDoppel exception: ' + e.message);
            return { success: false, error: e.message };
        }
    },

    updateAlertInDoppel: function (alertId, changes) {
        var QUEUE = ['doppel_review', 'needs_confirmation', 'actioned', 'taken_down', 'monitoring', 'archived'];
        var ENTITY = ['active', 'down', 'parked', 'suspicious', 'unclassified', 'unrelated', 'related', 'unknown'];
        changes = changes || {};
        alertId = String(alertId || '').trim();
        if (!alertId) return { success: false, error: 'alert_id is required' };

        var body = {};
        var q = String(changes.queue_state || '').trim();
        var e = String(changes.entity_state || '').trim();
        var c = String(changes.comment || '').trim();
        var ta = String(changes.tag_action || '').trim();
        var tn = String(changes.tag_name || '').trim();

        if (q) { if (QUEUE.indexOf(q) < 0) return { success: false, error: 'Invalid queue_state: ' + q }; body.queue_state = q; }
        if (e) { if (ENTITY.indexOf(e) < 0) return { success: false, error: 'Invalid entity_state: ' + e }; body.entity_state = e; }
        if (c) body.comment = c;
        if (ta || tn) {
            if (!ta || !tn) return { success: false, error: 'tag_action and tag_name must be provided together' };
            if (ta != 'add' && ta != 'remove') return { success: false, error: 'Invalid tag_action: ' + ta };
            body.tag_action = ta;
            body.tag_name = tn;
        }
        if (!Object.keys(body).length) return { success: false, error: 'Nothing to update: provide queue_state, entity_state, comment or a tag' };

        var headers = this._getAuthHeaders();
        if (!headers) return { success: false, error: 'No valid auth headers (check the Doppel TI Configuration)' };

        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this._getApiBase() + '/alert');
            r.setHttpMethod('PUT');
            for (var key in headers) r.setRequestHeader(key, headers[key]);
            r.setRequestHeader('Content-Type', 'application/json');
            r.setQueryParameter('id', alertId);
            r.setRequestBody(JSON.stringify(body));
            r.setHttpTimeout(15000);

            var response = r.execute();
            var status = response.getStatusCode();
            var respBody = response.getBody();

            if (status == 200) {
                var alert = null;
                try { var parsed = JSON.parse(respBody); if (parsed && parsed.id) alert = parsed; } catch (e1) { /* not an alert body */ }
                if (!alert) { var fresh = this.getAlertById(alertId); alert = fresh.success ? fresh.data : null; }
                var synced = false;
                if (alert) {
                    try { this._stageAlert(alert); synced = true; }
                    catch (e2) { gs.warn('DoppelIOCImport: updated ' + alertId + ' in Doppel but local sync failed: ' + e2.message); }
                }
                gs.info('DoppelIOCImport: updated alert ' + alertId + ' in Doppel ' + JSON.stringify(body) + ' | synced locally=' + synced);
                return { success: true, synced: synced, data: alert };
            }

            var msg = 'HTTP ' + status;
            try { var err = JSON.parse(respBody); if (err && err.message) msg = err.message + ' (HTTP ' + status + ')'; } catch (e3) { /* keep generic */ }
            if (status == 404) msg = 'Alert or tag not found (HTTP 404)';
            gs.error('DoppelIOCImport: updateAlertInDoppel ' + alertId + ' failed: ' + msg + ' | ' + String(respBody).substring(0, 300));
            return { success: false, error: msg };
        } catch (ex) {
            gs.error('DoppelIOCImport: updateAlertInDoppel exception for ' + alertId + ': ' + ex.message);
            return { success: false, error: ex.message };
        }
    },

    lookupIndicator: function (value, forceRefresh) {
		if (!forceRefresh) {
            var local = this.searchLocal(value);
            if (local && local.alert_id) {
                local.checkedDoppel = false;
                local.hit = true;
                return local;
            }
        }
        var apiResult = this.getAlertByEntity(value);
        if (!apiResult.success) {
            return { hit: false, error: apiResult.error };
        }
        if (!apiResult.data) {
            return { hit: false, checkedDoppel: true };
        }
        var a = apiResult.data;
        return {
            hit: true,
            checkedDoppel: true,
            alert_id: a.id,
            brand: a.brand,
            product_type: a.product,
            queue_state: a.queue_state,
            entity_state: a.entity_state,
            doppel_link: a.doppel_link
        };
    },

    // ---------------------------------------------------------------
    // Connection test (used by the Test Connectivity button)
    // ---------------------------------------------------------------

    testConnection: function () {
        var c = this._cfg();
        var version = c.version;
        var missing = [];
        if (version == 'v2') {
            if (!c.clientId) missing.push('Client ID');
            if (!c.clientSecret) missing.push('Client secret');
        } else {
            if (!c.apiKey) missing.push('API key');
            if (!c.userKey) missing.push('User API key');
        }
        if (missing.length) {
            return { success: false, auth_version: version, stage: 'config',
                     message: (c.found ? '' : 'No Doppel TI Configuration saved yet. ') +
                              'Missing required setting(s) for ' + version + ': ' + missing.join(', ') };
        }

        var headers = this._getAuthHeaders();
		if (!headers) {
            return { success: false, auth_version: version, stage: 'token',
                     message: this._v2RetryAfterMs
                         ? 'Doppel\'s token limit was reached (HTTP 429). Try again in about ' + Math.ceil(this._v2RetryAfterMs / 60000) + ' minutes.'
                         : 'Could not obtain a v2 access token. Check Client ID / Client secret (HTTP status is in System Logs).' };
        }

        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this._getApiBase() + '/alerts');
            r.setHttpMethod('GET');
            for (var key in headers) {
                r.setRequestHeader(key, headers[key]);
            }
            r.setQueryParameter('page', '0');
            r.setQueryParameter('page_size', '1');
            r.setHttpTimeout(15000);

            var response = r.execute();
            var status = response.getStatusCode();

            if (status == 200) {
                return { success: true, auth_version: version, stage: 'api', http_status: status,
                         message: 'Connected to Doppel (' + version + ').' };
            }

            var body = String(response.getBody() || '');
            var doppelMsg = '';
            try {
                var pj = JSON.parse(body);
                doppelMsg = pj.message || pj.error_description || '';
            } catch (e1) { /* not JSON */ }
            gs.error('DoppelIOCImport: testConnection HTTP ' + status + ': ' + body.substring(0, 300));

            var msg;
            if (status == 400 || status == 401 || status == 403) {
                msg = 'Doppel rejected the request (HTTP ' + status + ')' + (doppelMsg ? ': ' + doppelMsg : '.');
            } else if (status == 429) {
                msg = 'Rate limited by Doppel (HTTP 429). Wait a minute and retry.';
            } else if (status >= 500) {
                msg = 'Doppel returned a server error (HTTP ' + status + '). Retry later.';
            } else {
                msg = 'Unexpected response from Doppel (HTTP ' + status + ')' + (doppelMsg ? ': ' + doppelMsg : '.');
            }
            return { success: false, auth_version: version, stage: 'api', http_status: status, message: msg };
        } catch (e) {
            gs.error('DoppelIOCImport: testConnection exception: ' + e.message);
            return { success: false, auth_version: version, stage: 'network',
                     message: 'Could not reach Doppel: ' + e.message };
        }
    },

    // ---------------------------------------------------------------
    // Native Threat Lookup
    // ---------------------------------------------------------------

    runCapabilityThreatLookup: function (inputParams, executionSysId) {
        gs.info('DOPPEL LOOKUP | exec=' + executionSysId + ' | type=' + typeof inputParams + ' | value=' + String(inputParams).substring(0, 300));
        // Values of the sn_ti_observable.finding choice list (values, not labels)
        var FINDING = {
            MALICIOUS: 'Malicious',
            SUSPICIOUS: 'Suspicious',
            UNKNOWN: 'Unknown'
        };

        var params = inputParams;
        if (typeof params == 'string') {
            try { params = JSON.parse(params); } catch (e) { params = null; }
        }
        var ids = (params && params.sn_ti_observable) ? params.sn_ti_observable : [];
        if (!ids.length) {
            return { state: 'ERROR', status_message: 'No sn_ti_observable ids in input_parameters', summary: {} };
        }
        var vendorId = this._getDoppelIntegrationItemId();
        var summary = { processed: 0, hit: 0, no_match: 0, written: 0, skipped: 0, errors: 0 };
        var errors = [];
        var skipped = [];

        for (var i = 0; i < ids.length; i++) {
            summary.processed++;
            var obs = new GlideRecord('sn_ti_observable');
            if (!obs.get(ids[i])) {
                summary.errors++;
                errors.push('Observable not found: ' + ids[i]);
                continue;
            }
            var value = obs.getValue('value');
            var typeName = obs.getDisplayValue('type');
            if (!this._isDoppelSupported(typeName, value)) {
                summary.skipped++;
                skipped.push(value + ' (' + typeName + ')');
                this._upsertLookupResult(ids[i], vendorId, FINDING.UNKNOWN,
                    'Not checked by Doppel: unsupported observable type (' + typeName + ')',
                    'Doppel accepts URLs, domains, email addresses and phone numbers.',
                    '', '', executionSysId, true);
                continue;
            }
            // Analyst-triggered lookup always checks Doppel live
            var api = this.getAlertByEntity(value);
            if (!api.success) {
                var reason = this._apiErrorMessage(api);
                summary.errors++;
                errors.push(value + ': ' + reason);
                this._upsertLookupResult(ids[i], vendorId, FINDING.UNKNOWN,
                    'Doppel lookup failed: ' + reason,
                    'Check the value format (phone numbers need a + country code) or retry later.',
                    '', '', executionSysId, true);
                continue;
            }

            var finding, resultText, details = '', link = '', raw = '';
            if (api.data) {
                var a = api.data;
                summary.hit++;
                finding = this._mapDoppelFinding(a, FINDING);
                resultText = 'Doppel alert ' + a.id + ' (' + a.queue_state + ' / ' + a.entity_state + ')';
                details = 'Brand: ' + (a.brand || '-') +
                    ' | Product: ' + (a.product || '-') +
                    ' | Severity: ' + (a.severity || '-') +
                    ' | Score: ' + (a.score != null ? a.score : '-') +
                    ' | Queue: ' + (a.queue_state || '-') +
                    ' | Entity: ' + (a.entity_state || '-');
                link = a.doppel_link || '';
                raw = JSON.stringify({
                    id: a.id, entity: a.entity, brand: a.brand, product: a.product,
                    severity: a.severity, score: a.score, queue_state: a.queue_state,
                    entity_state: a.entity_state, doppel_link: a.doppel_link,
                    created_at: a.created_at
                });
            } else {
                summary.no_match++;
                finding = FINDING.UNKNOWN; // absence from Doppel is not proof the value is safe
                resultText = this.NO_MATCH_TEXT;
            }

            if (this._upsertLookupResult(ids[i], vendorId, finding, resultText, details, link, raw, executionSysId)) {
                summary.written++;
            } else {
                summary.errors++;
                errors.push(value + ': lookup result write failed');
            }
        }

        var ret = {
            state: (summary.written > 0 || summary.errors == 0) ? 'COMPLETE' : 'ERROR',
            status_message: 'Doppel: ' + summary.hit + ' hit, ' + summary.no_match + ' no match, ' +
                summary.skipped + ' skipped (unsupported type), ' + summary.errors + ' error(s)' +
                (skipped.length ? ' | Skipped: ' + skipped.join('; ') : '') +
                (errors.length ? ' | Errors: ' + errors.join('; ') : ''),
            summary: summary
        };
        gs.info('DOPPEL LOOKUP | result=' + JSON.stringify(ret));
        return ret;
    },

    _mapDoppelFinding: function (a, F) {
        var q = String(a.queue_state || '').toLowerCase();
        var e = String(a.entity_state || '').toLowerCase();
        // Dismissed, or Doppel says it isn't a threat to the brand
        if (q == 'archived' || e == 'unrelated' || e == 'related') return F.UNKNOWN;
        // Doppel confirmed and acted
        if (this._cfg().maliciousQueue.indexOf(q) > -1) return F.MALICIOUS;
        // Flagged by Doppel but not confirmed
        return F.SUSPICIOUS;
    },

    _apiErrorMessage: function (api) {
        try {
            var parsed = JSON.parse(api.raw || '');
            if (parsed && parsed.message) return parsed.message + ' (' + api.error + ')';
        } catch (e) { /* not JSON */ }
        return api.error || 'unknown error';
    },

    _isDoppelSupported: function (typeName, value) {
        var ALLOWED = ['URL', 'URI', 'Domain name', 'Host name', 'Email address', 'Phone number'];
        if (ALLOWED.indexOf(typeName) > -1) return true;
        // Rule engine classifies "domain.com/path" as File path — allow only web-shaped values
        if (typeName == 'File path' && value) {
            if (value.indexOf('\\') > -1 || value.charAt(0) == '/') return false;
            return /^(https?:\/\/)?[^\/\s]+\.[a-z]{2,}(\/|$)/i.test(value);
        }
        return false;
    },

    getLatestDoppelResult: function (obsId) {
        var r = new GlideRecord('sn_ti_lookup_result');
        r.addQuery('observable', obsId);
        var vendorId = this._getDoppelIntegrationItemId();
        if (vendorId) {
            r.addQuery('vendor', vendorId);
        } else {
            r.addQuery('source_engine', 'Doppel');
        }
        r.orderByDesc('sys_created_on');
        r.setLimit(1);
        r.query();
        return r.next() ? r : null;
    },

	getLatestDoppelLink: function (obsId) {
        var r = this.getLatestDoppelResult(obsId);
        if (r && r.getValue('external_link')) return r.getValue('external_link');

        // Fallback: Doppel link stored on the imported observable
        var obs = new GlideRecord('sn_ti_observable');
        if (obs.get(obsId)) return obs.getValue('x_doppe_doppel_t_0_doppel_link') || '';
        return '';
    },

    canSubmitToDoppel: function (obsGr) {
        if (!this._isDoppelSupported(obsGr.getDisplayValue('type'), obsGr.getValue('value'))) return false;
        var r = this.getLatestDoppelResult(obsGr.getUniqueValue());
        return !!r && r.getValue('result') == this.NO_MATCH_TEXT;
    },

    _upsertLookupResult: function (obsId, vendorId, finding, resultText, details, link, raw, execId, ignoreRollup) {
        var r = new GlideRecord('sn_ti_lookup_result');
        r.initialize();

        r.setValue('observable', obsId);
        if (vendorId) r.setValue('vendor', vendorId);
        r.setValue('source_engine', 'Doppel');
        r.setValue('source_engine_version', this._cfg().version);
        r.setValue('finding', finding);
        r.setValue('result', resultText);
        r.setValue('details', details);
        r.setValue('external_link', link);
        r.setValue('raw_data', raw);
        r.setValue('retrieval_date', new GlideDateTime().getDisplayValue());

        if (execId) {
            r.setValue('ref_table', 'sn_sec_cmn_capability_implementation_execution');
            r.setValue('ref_id', execId);
        }
        if (ignoreRollup) r.setValue('ignore_observable_finding_rollup', true);
        return !!r.insert();
    },

    _getDoppelIntegrationItemId: function () {
        var gr = new GlideRecord('sn_sec_core_integration_item');
        gr.addQuery('name', 'Doppel');
        gr.query();
        return gr.next() ? gr.getUniqueValue() : '';
    },

    // ---------------------------------------------------------------
    // Authentication
    // ---------------------------------------------------------------

    _getAuthHeaders: function () {
        var c = this._cfg();
        var headers = {};

        if (c.version == 'v2') {
            var token = this._getCachedV2AccessToken(this._forceNewToken);
            if (!token) {
                gs.error('DoppelIOCImport: _getAuthHeaders — could not obtain v2 access token');
                return null;
            }
            headers['Authorization'] = 'Bearer ' + token;
        } else {
            if (!c.apiKey || !c.userKey) {
                gs.error('DoppelIOCImport: v1 credentials missing (API key / user API key), request not sent');
                return null;
            }
            headers['x-api-key'] = c.apiKey;
            headers['x-user-api-key'] = c.userKey;
            // Required by Doppel only when the user belongs to more than one organisation
            if (c.orgCode) headers['x-organization-code'] = c.orgCode;
        }

        headers['x-doppel-client'] = this._getClientHeaderValue();
        return headers;
    },

    _getClientHeaderValue: function () {
        var slug = 'servicenow'; // still unconfirmed with your lead
        var version = '0.0.0';
        var gr = new GlideRecord('sys_scope');
        gr.addQuery('scope', 'x_doppe_doppel_t_0');
        gr.query();
        if (gr.next() && gr.getValue('version')) {
            version = gr.getValue('version');
        }
        return slug + '/' + version;
    },

    _getApiBase: function () {
        return this._cfg().version == 'v2' ? 'https://api.doppel.com/v2' : 'https://api.doppel.com/v1';
    },

	// v2 token is cached on the configuration record (24 h validity) so runs don't each mint one.
    // Doppel allows only a few token requests per client per hour.
    _getCachedV2AccessToken: function (forceNew) {
        var now = new GlideDateTime().getNumericValue();
        var c = this._cfg();
        this._v2RetryAfterMs = 0;
        if (!forceNew) {
            if (this._v2Token && this._v2TokenExpiry && now < this._v2TokenExpiry) return this._v2Token;
            var cache = this._readTokenCache();
            if (cache.clientId == c.clientId) {
                if (cache.token && now < cache.expires) {
                    this._v2Token = cache.token;
                    this._v2TokenExpiry = cache.expires;
                    return cache.token;
                }
                if (cache.retryAfter && now < cache.retryAfter) {
                    this._v2RetryAfterMs = cache.retryAfter - now;
                    gs.warn('DoppelIOCImport: Doppel token limit reached; no token request for another ' +
                            Math.ceil(this._v2RetryAfterMs / 60000) + ' min');
                    return null;
                }
            }
        }
        var token = this._getV2AccessToken();
		if (token) {
            this._v2Token = token;
            this._v2TokenExpiry = now + (86400 - 300) * 1000;
            this._writeTokenCache(c.clientId, token, this._v2TokenExpiry, 0);
            var until = new GlideDateTime();
            until.setNumericValue(this._v2TokenExpiry);
            gs.info('DoppelIOCImport: new v2 access token obtained' +
                    (forceNew ? ' (testing new credentials)' : ' (no valid cached token)') +
                    ' | reused until ' + until.getValue() + ' UTC');
        } else if (this._v2RetryAfterMs) {
            this._writeTokenCache(c.clientId, null, 0, now + this._v2RetryAfterMs);
        }
        return token;
    },

    _getV2AccessToken: function () {
        var c = this._cfg();
        this._v2RetryAfterMs = 0;
        if (!c.clientId || !c.clientSecret) {
            gs.error('DoppelIOCImport: _getV2AccessToken failed — Client ID or Client secret is empty');
            return null;
        }
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint('https://api.doppel.com/oauth/token');
            r.setHttpMethod('POST');
            r.setRequestHeader('Content-Type', 'application/json');
            r.setRequestHeader('x-doppel-client', this._getClientHeaderValue());
            r.setRequestBody(JSON.stringify({
                client_id: c.clientId,
                client_secret: c.clientSecret,
                audience: 'doppel-external',
                grant_type: 'client_credentials'
            }));
            r.setHttpTimeout(15000);

            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();

            if (status != 200) {
                if (status == 429) {
                    var secs = parseInt(response.getHeader('Retry-After'), 10);
                    if (!secs) {
                        var m = /retry after (\d+) seconds/i.exec(String(body));
                        secs = m ? parseInt(m[1], 10) : 3600;
                    }
                    this._v2RetryAfterMs = secs * 1000;
                }
                gs.error('DoppelIOCImport: _getV2AccessToken failed — HTTP ' + status + ': ' + String(body).substring(0, 300));
                return null;
            }
            var parsed = JSON.parse(body);
            if (!parsed.access_token) {
                gs.error('DoppelIOCImport: _getV2AccessToken failed — response missing access_token');
                return null;
            }
            return parsed.access_token;
        } catch (e) {
            gs.error('DoppelIOCImport: _getV2AccessToken exception: ' + e.message);
            return null;
        }
    },

    _configRecord: function () {
        var gr = new GlideRecord(this.CONFIG_TABLE);
        gr.orderBy('sys_created_on');
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr : null;
    },

    _readTokenCache: function () {
        var out = { token: '', clientId: '', expires: 0, retryAfter: 0 };
        var gr = this._configRecord();
        if (!gr) return out;
        try {
            var meta = JSON.parse(gr.getValue('v2_token_meta') || '{}');
            out.clientId = meta.clientId || '';
            out.expires = meta.expires || 0;
            out.retryAfter = meta.retryAfter || 0;
        } catch (e) { /* empty or invalid meta: no cache */ }
        out.token = gr.v2_token.getDecryptedValue() || '';
        return out;
    },

    _writeTokenCache: function (clientId, token, expires, retryAfter) {
        var gr = this._configRecord();
        if (!gr) return;   // nothing saved yet (e.g. testing a brand-new record)
        if (token !== null) gr.v2_token.setDisplayValue(token);
        gr.setValue('v2_token_meta', JSON.stringify({ clientId: clientId, expires: expires, retryAfter: retryAfter }));
        gr.setWorkflow(false);   // don't run the validate / schedule-sync business rules
        gr.update();
    },

    type: 'DoppelIOCImport'
};
